-- Lead Desk · territories (each area belongs to one sales engineer)
-- Run once in Supabase → SQL Editor. Safe to run again.
--
-- 1. Sales engineers can submit an outbound lead for a property in someone else's territory.
--    It arrives unassigned in the back-office queue and back office passes it to the territory owner.
--    (Their own-territory leads still arrive assigned to them, waiting for approval.)
drop policy if exists leads_insert on public.leads;
create policy leads_insert on public.leads for insert to authenticated with check (
  public.my_role() = 'backoffice'
  or (public.my_role() = 'sales'
      and public.my_engineer() <> ''
      and status = 'New'
      and doc->>'category' = 'Outbound'
      and ( lower(assigned_to) = lower(public.my_engineer())
            or (coalesce(assigned_to, '') = '' and lower(doc->>'generatedBy') = lower(public.my_engineer())) ))
);

-- 2. Starting territory list, taken from who handled each country in the 2026 leads.
--    Only added if no territories have been saved yet; back office reviews it under Products & settings → Territories.
update public.docs
set doc = doc || jsonb_build_object('territories', $j$[{"area": "UAE", "engineer": "Shijith"}, {"area": "India", "engineer": "Nidhin"}, {"area": "UK", "engineer": "Pablo"}, {"area": "USA", "engineer": "Don"}, {"area": "Thailand", "engineer": "Shahzaman"}, {"area": "Japan", "engineer": "Rodjard"}, {"area": "Saudi Arabia", "engineer": "Imtishal"}, {"area": "Malaysia", "engineer": "Shahbaz"}, {"area": "Qatar", "engineer": "Shijith"}, {"area": "Vietnam", "engineer": "Shahbaz"}, {"area": "Spain", "engineer": "Pablo"}, {"area": "Morocco", "engineer": "Burhan"}, {"area": "France", "engineer": "Prajwal"}, {"area": "Germany", "engineer": "Mubeen"}, {"area": "Singapore", "engineer": "Rodjard"}, {"area": "Netherlands", "engineer": "Vishnu"}, {"area": "Indonesia", "engineer": "Shahbaz"}, {"area": "Hungary", "engineer": "Himani"}, {"area": "Australia", "engineer": "Shahbaz"}, {"area": "Philippines", "engineer": "Rodjard"}, {"area": "Oman", "engineer": "Burhan"}, {"area": "Italy", "engineer": "Burhan"}, {"area": "Egypt", "engineer": "Mubeen"}, {"area": "South Africa", "engineer": "Burhan"}, {"area": "Maldives", "engineer": "Nidhin"}, {"area": "Georgia", "engineer": "Mustafa"}, {"area": "Kenya", "engineer": "Burhan"}, {"area": "Portugal", "engineer": "Pablo"}, {"area": "Tanzania", "engineer": "Prajwal"}, {"area": "Malta", "engineer": "Pablo"}, {"area": "Greece", "engineer": "Mustafa"}, {"area": "Sri Lanka", "engineer": "Nidhin"}, {"area": "Bahrain", "engineer": "Mubeen"}, {"area": "Switzerland", "engineer": "Pablo"}, {"area": "Mexico", "engineer": "Don"}, {"area": "Kuwait", "engineer": "Mubeen"}, {"area": "Nigeria", "engineer": "Burhan"}, {"area": "Cambodia", "engineer": "Shahzaman"}, {"area": "Fiji", "engineer": "Shahbaz"}, {"area": "Azerbaijan", "engineer": "Mubeen"}, {"area": "Nepal", "engineer": "Nidhin"}, {"area": "New Zealand", "engineer": "Shahbaz"}, {"area": "Belgium", "engineer": "Vishnu"}, {"area": "Turkey", "engineer": "Mustafa"}, {"area": "Sweden", "engineer": "Mubeen"